import csv
from datetime import datetime, timezone
import json, sys

def parse_iso_timestamp(ts):
    dt = datetime.fromisoformat(ts)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)

def parse_transactions(csv_file):
    records = {}
    with open(csv_file, mode='r', encoding='utf-8') as f:
        for row in csv.DictReader(f):
            tx_id = row['tx_id'].strip()
            dt = parse_iso_timestamp(row['timestamp'].strip())
            amt = float(row['amount'].strip())
            st = row['status'].strip().upper()
            if tx_id not in records or dt > records[tx_id]['dt']:
                records[tx_id] = {'dt': dt, 'amount': amt, 'status': st}
    v_cnt = sum(1 for r in records.values() if r['status'] == 'SUCCESS')
    f_cnt = sum(1 for r in records.values() if r['status'] == 'FAILED')
    tot = sum(r['amount'] for r in records.values() if r['status'] == 'SUCCESS')
    return {'total_valid_amount': round(tot, 2), 'valid_count': v_cnt, 'failed_count': f_cnt}

if __name__ == '__main__':
    if len(sys.argv) < 2: sys.exit(1)
    print(json.dumps(parse_transactions(sys.argv[1]), indent=2))
